<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';$rows=[];try{$db=pv_db();if(pv_table_exists('news')){$r=$db->query('SELECT * FROM news WHERE is_published=1 ORDER BY published_at DESC LIMIT 30');if($r)while($x=$r->fetch_assoc())$rows[]=$x;}}catch(Throwable){}pv_page_start('Network News','news.php',pv_is_logged_in());?>
<main class="nxt-document"><section class="pv-card nxt-document-panel"><div class="nxt-document-head"><div><span class="pv-eyebrow">NXT NETWORK BULLETIN</span><h1>Network News</h1></div><?=nxt_sprite('biyomon')?></div><p class="pv-subtle">Server announcements, research notes and Cyberspace status updates.</p><?php if(!$rows):?><div class="pv-empty">No transmissions yet. Check back for the next network update.</div><?php else:?><div class="pv-message-list"><?php foreach($rows as $n):?><article class="pv-news-item" style="padding:16px 0"><small><?=pv_h(strtoupper((string)$n['category']))?> // <?=date('Y-m-d',(int)$n['published_at'])?></small><h2><?=pv_h((string)$n['title'])?></h2><p><?=nl2br(pv_h((string)$n['body']))?></p></article><?php endforeach;?></div><?php endif;?></section></main><?php pv_page_end(); ?>
